        for si in tree.findall('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}si'):
            t = si.find('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t')
            if t is not None:
                sst.append(t.text or '')
            else:
                text = ''.join([elem.text or '' for elem in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t')])
                sst.append(text)

    # Let's inspect all sheets
    wb_tree = ET.fromstring(z.read('xl/workbook.xml'))
    sheet_map = {}
    for s in wb_tree.findall('.//{http://schemas.openxmlformats.org/spreadsheetml/2006/main}sheet'):
        sheet_map[s.attrib['name']] = s.attrib['{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id']

    rels_tree = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    rel_targets = {r.attrib['Id']: r.attrib['Target'] for r in rels_tree.findall('.//{http://schemas.openxmlformats.org/package/2006/relationships}Relationship')}

    for sname, rId in sheet_map.items():
        target = 'xl/' + rel_targets[rId] if not rel_targets[rId].startswith('xl/') else rel_targets[rId]
        tree = ET.fromstring(z.read(target))
        rows = tree.findall('.//{http://schemas.openxmlformats.org/spreadsheetml/2006/main}row')
        print(f'=== Sheet: {sname} (Rows: {len(rows)}) ===')
